import copy
import hashlib
import json
import math
import random
from pathlib import Path


def require(condition, message):
    if not condition:
        raise AssertionError(message)


def expect_error(name, exception_type, function):
    try:
        function()
    except exception_type:
        print("NEGATIVE", name, "PASS")
        return
    raise AssertionError(name + " did not raise " + exception_type.__name__)


def immutable_fixture(path):
    raw = json.loads(Path(path).read_text(encoding="utf-8"))
    if not isinstance(raw, dict):
        raise TypeError("fixture root must be an object")
    responses = raw.get("responses")
    if not isinstance(responses, list) or not responses or not all(isinstance(x, str) and x for x in responses):
        raise TypeError("responses must be nonempty strings")
    if len(set(responses)) != len(responses):
        raise ValueError("duplicate response")

    def rows(name):
        value = raw.get(name)
        if not isinstance(value, list) or not value:
            raise TypeError(name + " must be a nonempty array")
        answer = []
        for item in value:
            if not isinstance(item, dict):
                raise TypeError("pair must be an object")
            if set(item) != {"prompt", "chosen", "rejected"}:
                raise ValueError("pair fields invalid")
            p, c, r = item["prompt"], item["chosen"], item["rejected"]
            if not all(isinstance(x, str) for x in (p, c, r)):
                raise TypeError("pair fields must be strings")
            if not p or not c or not r:
                raise ValueError("empty prompt or completion")
            if c == r:
                raise ValueError("chosen equals rejected")
            if c not in responses or r not in responses:
                raise ValueError("completion outside response vocabulary")
            answer.append((p, c, r))
        return tuple(answer)

    train = rows("train")
    in_holdout = rows("in_holdout")
    shifted = rows("shifted")
    seen = set()
    for split_name, split in (("train", train), ("in_holdout", in_holdout), ("shifted", shifted)):
        for p, _, _ in split:
            if p in seen:
                raise ValueError("duplicate prompt across splits: " + p)
            seen.add(p)

    feature_source = copy.deepcopy(raw.get("features", {}))
    feature_source.update(copy.deepcopy(raw.get("in_holdout_features", {})))
    if not isinstance(feature_source, dict):
        raise TypeError("features must be an object")
    features = {}
    for p in seen:
        fs = feature_source.get(p)
        if not isinstance(fs, list) or not fs or not all(isinstance(x, str) and x for x in fs):
            raise ValueError("missing or invalid features for " + p)
        features[p] = tuple(fs)

    expected_raw = raw.get("judge_expected")
    if not isinstance(expected_raw, dict):
        raise TypeError("judge_expected must be an object")
    eval_prompts = {p for p, _, _ in in_holdout + shifted}
    if set(expected_raw) != eval_prompts:
        raise ValueError("judge labels must cover exactly the evaluation prompts")
    expected = {}
    for p, answer in expected_raw.items():
        if not isinstance(answer, str) or answer not in responses:
            raise ValueError("invalid judge answer")
        expected[p] = answer

    return {
        "responses": tuple(responses),
        "train": train,
        "in_holdout": in_holdout,
        "shifted": shifted,
        "features": features,
        "judge_expected": expected,
    }


def stable_logsoftmax(values):
    if not values or not all(isinstance(x, (int, float)) and not isinstance(x, bool) and math.isfinite(x) for x in values):
        raise ValueError("logits must be finite numbers")
    maximum = max(values)
    log_z = maximum + math.log(sum(math.exp(x - maximum) for x in values))
    return tuple(x - log_z for x in values)


def sigmoid(x):
    if x >= 0.0:
        return 1.0 / (1.0 + math.exp(-x))
    e = math.exp(x)
    return e / (1.0 + e)


def stable_logsigmoid(x):
    if x >= 0.0:
        return -math.log1p(math.exp(-x))
    return x - math.log1p(math.exp(x))


def new_model(responses, feature_names):
    return {
        "bias": {r: 0.0 for r in responses},
        "weight": {f: {r: 0.0 for r in responses} for f in sorted(feature_names)},
    }


def logits(model, prompt, responses, features):
    if prompt not in features:
        raise KeyError("unknown prompt")
    result = []
    for r in responses:
        value = model["bias"][r]
        for f in features[prompt]:
            value += model["weight"][f][r]
        result.append(value)
    return tuple(result)


def logp(model, prompt, response, responses, features):
    if response not in responses:
        raise KeyError("unknown response")
    return stable_logsoftmax(logits(model, prompt, responses, features))[responses.index(response)]


def digest(model):
    payload = json.dumps(model, sort_keys=True, separators=(",", ":"), allow_nan=False)
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def snapshot(model):
    result = {}
    for r, value in sorted(model["bias"].items()):
        if abs(value) > 1e-12:
            result["bias/" + r] = round(value, 8)
    for f, row in sorted(model["weight"].items()):
        for r, value in sorted(row.items()):
            if abs(value) > 1e-12:
                result["weight/" + f + "/" + r] = round(value, 8)
    return result


def sft(model, rows, responses, features, steps=12, learning_rate=0.12):
    if not isinstance(steps, int) or isinstance(steps, bool) or steps < 0:
        raise ValueError("steps must be a nonnegative integer")
    out = copy.deepcopy(model)
    for _ in range(steps):
        for prompt, chosen, _ in rows:
            probabilities = tuple(math.exp(x) for x in stable_logsoftmax(logits(out, prompt, responses, features)))
            for index, response in enumerate(responses):
                gradient = probabilities[index] - float(response == chosen)
                out["bias"][response] -= learning_rate * gradient
                for feature in features[prompt]:
                    out["weight"][feature][response] -= learning_rate * gradient
    return out


def pair_z(policy, reference, row, beta, responses, features):
    prompt, chosen, rejected = row
    chosen_ratio = logp(policy, prompt, chosen, responses, features) - logp(reference, prompt, chosen, responses, features)
    rejected_ratio = logp(policy, prompt, rejected, responses, features) - logp(reference, prompt, rejected, responses, features)
    return beta * (chosen_ratio - rejected_ratio)


def pair_loss(policy, reference, row, beta, responses, features):
    return -stable_logsigmoid(pair_z(policy, reference, row, beta, responses, features))


def checked_beta(beta):
    if not isinstance(beta, (int, float)) or isinstance(beta, bool) or not math.isfinite(beta) or beta <= 0.0:
        raise ValueError("beta must be a positive finite number")
    return float(beta)


def dpo(model, reference, rows, beta, responses, features, steps=24, learning_rate=0.08):
    beta = checked_beta(beta)
    if not isinstance(steps, int) or isinstance(steps, bool) or steps < 0:
        raise ValueError("steps must be a nonnegative integer")
    out = copy.deepcopy(model)
    for _ in range(steps):
        for row in rows:
            prompt, chosen, rejected = row
            before = pair_loss(out, reference, row, beta, responses, features)
            scale = beta * sigmoid(-pair_z(out, reference, row, beta, responses, features))
            out["bias"][chosen] += learning_rate * scale
            out["bias"][rejected] -= learning_rate * scale
            for feature in features[prompt]:
                out["weight"][feature][chosen] += learning_rate * scale
                out["weight"][feature][rejected] -= learning_rate * scale
            after = pair_loss(out, reference, row, beta, responses, features)
            require(after < before, "DPO gradient step did not decrease pair loss")
    return out


def metrics(policy, reference, rows, beta, responses, features):
    values = []
    for prompt, chosen, rejected in rows:
        chosen_logp = logp(policy, prompt, chosen, responses, features)
        rejected_logp = logp(policy, prompt, rejected, responses, features)
        chosen_reward = beta * (chosen_logp - logp(reference, prompt, chosen, responses, features))
        rejected_reward = beta * (rejected_logp - logp(reference, prompt, rejected, responses, features))
        values.append((chosen_logp, rejected_logp, chosen_reward, rejected_reward, chosen_reward - rejected_reward))
    count = len(values)
    mean = lambda index: sum(row[index] for row in values) / count
    return {
        "logps_chosen": round(mean(0), 8),
        "logps_rejected": round(mean(1), 8),
        "rewards_chosen": round(mean(2), 8),
        "rewards_rejected": round(mean(3), 8),
        "rewards_margin": round(mean(4), 8),
        "rewards_accuracy": round(sum(row[4] > 0.0 for row in values) / count, 8),
    }


def sample(model, prompt, temperature, seed, responses, features):
    if not isinstance(temperature, (int, float)) or isinstance(temperature, bool) or not math.isfinite(temperature) or temperature <= 0.0:
        raise ValueError("temperature must be positive and finite")
    scaled = tuple(x / temperature for x in logits(model, prompt, responses, features))
    probabilities = tuple(math.exp(x) for x in stable_logsoftmax(scaled))
    draw = random.Random(seed).random()
    cumulative = 0.0
    for response, probability in zip(responses, probabilities):
        cumulative += probability
        if draw <= cumulative:
            return response
    return responses[-1]


def rubric(prompt, first, second, expected):
    required = expected[prompt]
    first_correct = int(first == required)
    second_correct = int(second == required)
    if first_correct != second_correct:
        return "FIRST" if first_correct > second_correct else "SECOND"
    if len(first) != len(second):
        return "FIRST" if len(first) < len(second) else "SECOND"
    return "TIE"


def position_biased_judge(prompt, first, second, expected):
    return "FIRST"


def identity_verdict(prompt, policy_text, reference_text, expected, judge):
    forward = judge(prompt, policy_text, reference_text, expected)
    reverse = judge(prompt, reference_text, policy_text, expected)
    forward_identity = {"FIRST": "POLICY", "SECOND": "REFERENCE", "TIE": "TIE"}[forward]
    reverse_identity = {"FIRST": "REFERENCE", "SECOND": "POLICY", "TIE": "TIE"}[reverse]
    consistent = forward_identity == reverse_identity
    if consistent and forward_identity == "POLICY":
        score = "win"
    elif consistent and forward_identity == "REFERENCE":
        score = "loss"
    else:
        score = "tie"
    return score, consistent, forward, reverse


def evaluate(policy, reference, rows, temperature, seed, responses, features, expected):
    counts = {"win": 0, "tie": 0, "loss": 0}
    samples = []
    consistent_count = 0
    winner_lengths = []
    loser_lengths = []
    for index, (prompt, _, _) in enumerate(rows):
        policy_text = sample(policy, prompt, temperature, seed + index, responses, features)
        reference_text = sample(reference, prompt, temperature, seed + 1000 + index, responses, features)
        score, consistent, forward, reverse = identity_verdict(prompt, policy_text, reference_text, expected, rubric)
        counts[score] += 1
        consistent_count += int(consistent)
        if score == "win":
            winner_lengths.append(len(policy_text))
            loser_lengths.append(len(reference_text))
        elif score == "loss":
            winner_lengths.append(len(reference_text))
            loser_lengths.append(len(policy_text))
        samples.append({
            "prompt": prompt,
            "policy_text": policy_text,
            "reference_text": reference_text,
            "forward_verdict": forward,
            "swapped_verdict": reverse,
            "score": score,
        })
    mean_or_unknown = lambda xs: round(sum(xs) / len(xs), 8) if xs else None
    return {
        "temperature": temperature,
        "counts": counts,
        "swap_consistency": round(consistent_count / len(rows), 8),
        "mean_winner_characters": mean_or_unknown(winner_lengths),
        "mean_loser_characters": mean_or_unknown(loser_lengths),
        "samples": samples,
    }


def finite_difference_check(responses, features):
    model = new_model(responses, {f for fs in features.values() for f in fs})
    reference = copy.deepcopy(model)
    row = ("sky report", "blue", "green")
    beta = 0.7
    epsilon = 1e-6
    analytic = -beta * sigmoid(-pair_z(model, reference, row, beta, responses, features))
    plus = copy.deepcopy(model)
    minus = copy.deepcopy(model)
    plus["weight"]["color"]["blue"] += epsilon
    minus["weight"]["color"]["blue"] -= epsilon
    numeric = (pair_loss(plus, reference, row, beta, responses, features) - pair_loss(minus, reference, row, beta, responses, features)) / (2.0 * epsilon)
    require(abs(analytic - numeric) < 1e-6, "finite-difference derivative mismatch")
    learning_rate = 0.01
    updated = dpo(model, reference, (row,), beta, responses, features, steps=1, learning_rate=learning_rate)
    actual_delta = updated["weight"]["color"]["blue"] - model["weight"]["color"]["blue"]
    require(abs(actual_delta - (-learning_rate * numeric)) < 1e-8, "optimizer is not negative numeric gradient")
    print("GRADIENT finite_difference PASS")
    print("GRADIENT optimizer_negative_numeric PASS")


def run_negative_tests(data):
    responses = data["responses"]
    features = data["features"]
    feature_names = {f for fs in features.values() for f in fs}
    base = new_model(responses, feature_names)
    reference = sft(base, data["train"], responses, features, steps=1)

    def duplicate_split():
        seen = set()
        for split in ((("x", "blue", "green"),), (("x", "safe", "unsafe"),)):
            for prompt, _, _ in split:
                if prompt in seen:
                    raise ValueError("duplicate prompt across splits")
                seen.add(prompt)

    expect_error("duplicate_split", ValueError, duplicate_split)
    expect_error("invalid_equal_pair", ValueError, lambda: validate_single_pair(("x", "blue", "blue"), responses))
    expect_error("empty_completion", ValueError, lambda: validate_single_pair(("x", "", "green"), responses))
    expect_error("nonfinite_beta", ValueError, lambda: dpo(reference, reference, data["train"], float("nan"), responses, features))

    frozen_hash = digest(reference)
    policy = dpo(reference, reference, data["train"], 0.1, responses, features, steps=1)
    require(digest(reference) == frozen_hash, "reference mutated during DPO")
    policy["bias"][responses[0]] += 99.0
    require(digest(reference) == frozen_hash, "policy aliases reference")
    print("NEGATIVE reference_mutation PASS")

    unchanged = dpo(reference, reference, data["train"], 0.1, responses, features, steps=0)
    require(unchanged == reference and unchanged is not reference, "zero-step result changed or aliased input")
    print("NEGATIVE zero_step_unchanged PASS")

    prompt = next(iter(data["judge_expected"]))
    score, consistent, _, _ = identity_verdict(prompt, "blue", "green", data["judge_expected"], position_biased_judge)
    require(not consistent and score == "tie", "position-biased judge was not exposed by swapping")
    print("NEGATIVE position_bias_detected PASS")


def validate_single_pair(row, responses):
    if not isinstance(row, tuple) or len(row) != 3 or not all(isinstance(x, str) for x in row):
        raise TypeError("pair must be a three-string tuple")
    prompt, chosen, rejected = row
    if not prompt or not chosen or not rejected:
        raise ValueError("empty pair field")
    if chosen == rejected:
        raise ValueError("chosen equals rejected")
    if chosen not in responses or rejected not in responses:
        raise ValueError("unknown completion")
    return row


def main():
    data = immutable_fixture("fixtures.json")
    responses = data["responses"]
    features = data["features"]
    feature_names = {f for fs in features.values() for f in fs}
    base = new_model(responses, feature_names)
    base_hash = digest(base)
    reference = sft(base, data["train"], responses, features)
    reference_hash = digest(reference)
    require(digest(base) == base_hash, "SFT mutated its input")
    print("SNAPSHOT", json.dumps({"stage": "initial", "hash": base_hash, "parameters": snapshot(base)}, sort_keys=True))
    print("SNAPSHOT", json.dumps({"stage": "sft_reference", "hash": reference_hash, "parameters": snapshot(reference)}, sort_keys=True))

    finite_difference_check(responses, features)
    run_negative_tests(data)

    for beta in (0.1, 0.5):
        before_train = metrics(reference, reference, data["train"], beta, responses, features)
        policy = dpo(reference, reference, data["train"], beta, responses, features)
        require(digest(reference) == reference_hash, "frozen reference changed")
        after_train = metrics(policy, reference, data["train"], beta, responses, features)
        require(before_train["rewards_margin"] == 0.0, "reference margin should be zero")
        require(after_train["rewards_margin"] > before_train["rewards_margin"], "trained margin did not improve")
        require(after_train["rewards_accuracy"] > before_train["rewards_accuracy"], "trained reward accuracy did not improve")
        print("SNAPSHOT", json.dumps({"stage": "dpo", "beta": beta, "hash": digest(policy), "parameters": snapshot(policy)}, sort_keys=True))
        for split_name, rows in (("train", data["train"]), ("in_holdout", data["in_holdout"]), ("shifted", data["shifted"])):
            print("METRICS", json.dumps({"stage": "before", "beta": beta, "split": split_name, **metrics(reference, reference, rows, beta, responses, features)}, sort_keys=True))
            print("METRICS", json.dumps({"stage": "after", "beta": beta, "split": split_name, **metrics(policy, reference, rows, beta, responses, features)}, sort_keys=True))
        for split_name, rows in (("in_holdout", data["in_holdout"]), ("shifted", data["shifted"])):
            for temperature in (0.5, 1.2):
                report = evaluate(policy, reference, rows, temperature, 4200 + int(beta * 100), responses, features, data["judge_expected"])
                print("EVAL", json.dumps({"beta": beta, "split": split_name, **report}, sort_keys=True))
        print("BETA", beta, "loss_decreased PASS")
        print("BETA", beta, "margin_improved PASS")
        print("BETA", beta, "reference_frozen PASS")

    print("ALL_CHECKS PASS")


if __name__ == "__main__":
    main()
